import * as THREE from 'three';

const $=s=>document.querySelector(s), gameEl=$('#game');
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x9ab7bf); scene.fog=new THREE.FogExp2(0x9ab7bf,.0019);
